import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import { SkeletonLoader } from '@hexa-ui/components';

type SkeletonGap = 'small' | 'medium' | 'large';
type SkeletonBorderRadius =
  'none' | 'x-small' | 'small' | 'medium' | 'large' | 'x-large';

interface StyledSkeletonContainerProps {
  $gap?: SkeletonGap;
}

export const StyledSkeletonContainer = styled.div<StyledSkeletonContainerProps>(
  ({ $gap }) => ({
    display: 'flex',
    flex: 1,
    ...($gap === 'small' && { gap: '8px' }),
    ...($gap === 'medium' && { gap: '16px' }),
    ...($gap === 'large' && { gap: '24px' }),
  }),
);

const borderRadiusStyles: Record<SkeletonBorderRadius, object> = {
  none: { borderRadius: 'none' },
  'x-small': { borderRadius: '4px !important' },
  small: { borderRadius: '8px !important' },
  medium: { borderRadius: '16px !important' },
  large: { borderRadius: '24px !important' },
  'x-large': { borderRadius: '32px !important' },
};

export const StyledSkeletonLoader = styled(SkeletonLoader, {
  shouldForwardProp: (propName) => propName !== '$borderRadius',
})<{
  $borderRadius?: SkeletonBorderRadius;
}>(
  ({ $borderRadius = 'small' }) =>
    borderRadiusStyles[$borderRadius] as CSSObject,
);
